; ----------
; Pass 1 for Uppercase to Lowercase conversion
; Left AND Right currently Roman Script
; ----------

pass ( Unicode )

; convert all characters to lower case
;

; reviewed for fub
class[UpperCase] = ( U+0041..U+005A U+0181 U+018A U+014A U+01B3)
class[LowerCase] = ( U+0061..U+007A U+0253 U+0257 U+014B U+01B4)


[UpperCase]    >  [LowerCase]

; ----------
; Pass 2a for the joined words
; Left AND Right currently Roman Script
; ----------

