; Pass 3b for the main converter
; Left currently Roman Script, Right now Arabic Script
; ----------

pass ( Unicode )

class[vowel] = ( "a" "e" "i" "o" "u" )

UniClass [WordBreak] = ( _WordBreak ) 

UniClass [Sp] = ( _Sp )

; inline sfms

"\x " > "\x "
"\xo " > "\xo "
"\xt " > "\xt "
"\xt*" > "\xt*"
"\x*" > "\x*"
"\ior " > "\ior "
"\ior*" > "\ior*"
"\f " > "\f "
"\fr " > "\fr "
"\fq " > "\fq "
"\ft " > "\ft "
"\f*" > "\f*"
"\k " > "\k "
"\k*" > "\k*"
"\th1 " > "\th1 "
"\w " > "\w "
"\w*" > "\w*"
"\bk " > "\bk "
"\bk*" > "\bk*"
"\tl " > "\tl "
"\tl*" > "\tl*"


; deleted dipthongs as I see no mention of them for fub

; take care of vowels next
; check long (doubled) forms first
; note that word initial forms are different and "ee" word final seems to be different
"aa" / (#|[WordBreak]) _  >   U+0639 U+064E U+0627  ; word initial
"aa"                      >   U+064E U+0627         ; medial and final same
"a"  / (#|[WordBreak]) _  >   U+0639 U+064E         ; word initial
"a"                       >   U+064E	              ; medial and final same
"ee" / (#|[WordBreak]) _  >   U+0639 U+065C U+0649 U+0670  ; word initial
"ee"                      >   U+065C U+0649 U+0670 ; word medial
"ee" / _ (#|[WordBreak])  >   U+065C U+0649        ; word final 
"e" / (#|[WordBreak]) _  >   U+0639 U+065C        ; word initial
"e"                       >   U+065C	             ; medial and final same
"ii" / (#|[WordBreak]) _  >   U+0639 U+0650 U+064A U+200D ; word initial
"ii"                      >   U+0650 U+064A U+200D ; medial and final same
"i" / (#|[WordBreak]) _  >   U+0639 U+0650        ; word initial
"i"                       >   U+0650               ; word medial and final same
"oo" / (#|[WordBreak]) _  >   U+0639 U+065B U+0648 U+200D ; word initial
"oo"                      >   U+065B U+0648 U+200D       ; word medial and final same
"o"  / (#|[WordBreak]) _  >   U+0639 U+065B        ; word initial
"o"                       >   U+065B               ; word medial and final same
"uu" / (#|[WordBreak]) _  >   U+0639 U+064F U+0648 U+200D ; word initial
"uu"                      >   U+064F U+0648 U+200D        ; word medial and final same
"u" / (#|[WordBreak]) _  >   U+0639 U+064F        ; word initial
"u"                       >   U+064F               ; word medial and final same

class[BackV] = ("a" "y" "u" "o")


class[ConsonantLatin] = ("b"    "c"    "d"     "f"    "g"    "h"    "j" \
                         "k"    "l"    "m"     "n"    "p"    "r"    "s" \
                         "t"    "w"    "y"     "z"    U+0253 U+0257 U+01B4 U+02BB U+2019 U+0027 U+02BC)         ; hook d, hook y, turned comma, glottal
class[ConsonantArabic] = (U+0628 U+0634 U+062F U+06A2 U+063A U+062D U+062C \
